div.script:

(function () {
    const apiCatalog = JSON.parse(
        document.getElementById('api_catalog_data').textContent || '[]'
    );
    const selector = document.getElementById('api_selector');
    const methodInput = document.getElementById('http_method');
    const endpointInput = document.getElementById('endpoint_path');
    const payloadInput = document.getElementById('request_payload');
    const resultBox = document.getElementById('result_box');
    const resultStatus = document.getElementById('result_status');
    const apiNote = document.getElementById('api_note');
    const resetButton = document.getElementById('reset_sample');
    const clearButton = document.getElementById('clear_result');
    const clearTokensButton = document.getElementById('clear_tokens');
    const sendButton = document.getElementById('send_request');
    const accessTokenBox = document.getElementById('access_token_box');
    const refreshTokenBox = document.getElementById('refresh_token_box');

    let accessToken = window.localStorage.getItem('acpec_ft_access_token') || '';
    let refreshToken = window.localStorage.getItem('acpec_ft_refresh_token') || '';
    let lastOtpIdentifier = window.localStorage.getItem('acpec_ft_last_otp_identifier') || '';
    let lastOtpChallengeId = window.localStorage.getItem('acpec_ft_last_otp_challenge_id') || '';
    let lastOtpCode = window.localStorage.getItem('acpec_ft_last_otp_code') || '000000';
    let lastSignupPayload = {};
    try {
        lastSignupPayload = JSON.parse(window.localStorage.getItem('acpec_ft_last_signup_payload') || '{}');
    } catch (error) {
        lastSignupPayload = {};
    }
    if (lastOtpCode && String(lastOtpCode).length !== 6) {
        lastOtpCode = '000000';
        window.localStorage.setItem('acpec_ft_last_otp_code', lastOtpCode);
    }
    if (lastSignupPayload && lastSignupPayload.secret_code && String(lastSignupPayload.secret_code).length !== 4) {
        lastSignupPayload.secret_code = '';
        window.localStorage.setItem('acpec_ft_last_signup_payload', JSON.stringify(lastSignupPayload));
    }

    function syncTokenBoxes() {
        accessTokenBox.value = accessToken || '';
        refreshTokenBox.value = refreshToken || '';
    }

    function saveTokens(newAccessToken, newRefreshToken) {
        if (newAccessToken) {
            accessToken = newAccessToken;
            window.localStorage.setItem('acpec_ft_access_token', accessToken);
        }
        if (newRefreshToken) {
            refreshToken = newRefreshToken;
            window.localStorage.setItem('acpec_ft_refresh_token', refreshToken);
        }
        syncTokenBoxes();
    }

    function clearTokens() {
        accessToken = '';
        refreshToken = '';
        window.localStorage.removeItem('acpec_ft_access_token');
        window.localStorage.removeItem('acpec_ft_refresh_token');
        syncTokenBoxes();
    }

    function captureTokens(result) {
        const data = result && result.result && result.result.data ? result.result.data : {};
        saveTokens(data.access_token, data.refresh_token);
    }

    function deepClone(value) {
        return JSON.parse(JSON.stringify(value || {}));
    }

    function captureOtpContext(result, submittedPayload, endpoint) {
        const data = result && result.result && result.result.data ? result.result.data : {};
        const submitted = submittedPayload || {};
        const route = endpoint || '';

        if (route.indexOf('/signup') !== -1 && route.indexOf('/signup-companies') === -1) {
            lastSignupPayload = {
                name: submitted.name || data.name || '',
                secret_code: submitted.secret_code || '',
                company_id: submitted.company_id || data.company_id || false,
                email: submitted.email || '',
                note: submitted.note || ''
            };
            window.localStorage.setItem('acpec_ft_last_signup_payload', JSON.stringify(lastSignupPayload));
        }
        const identifier = data.signup_identifier || data.identifier || '';
        const challengeId = data.otp_challenge_id || data.challenge_id || '';
        const code = data.otp_dev_code || data.dev_otp_code || '';

        if (identifier) {
            lastOtpIdentifier = identifier;
            window.localStorage.setItem('acpec_ft_last_otp_identifier', lastOtpIdentifier);
        }
        if (challengeId) {
            lastOtpChallengeId = String(challengeId);
            window.localStorage.setItem('acpec_ft_last_otp_challenge_id', lastOtpChallengeId);
        }
        if (code) {
            lastOtpCode = code;
            window.localStorage.setItem('acpec_ft_last_otp_code', lastOtpCode);
        }
    }

    function applyOtpContext(item, payload) {
        const route = item && item.route ? item.route : '';
        if (route.indexOf('/verify-otp') === -1) {
            return payload;
        }
        if (lastOtpIdentifier) {
            payload.identifier = lastOtpIdentifier;
        }
        if (lastOtpChallengeId) {
            const parsedChallengeId = parseInt(lastOtpChallengeId, 10);
            if (!isNaN(parsedChallengeId)) {
                payload.challenge_id = parsedChallengeId;
            }
        }
        payload.code = lastOtpCode || '000000';

        // Pour un challenge de type register, le vrai endpoint verify-otp
        // exige les mêmes informations métier que le signup.
        // On ne rend pas l'endpoint production plus permissif :
        // la console reprend simplement le payload du dernier signup.
        if (lastSignupPayload && lastSignupPayload.name) {
            payload.name = lastSignupPayload.name;
        }
        if (lastSignupPayload && lastSignupPayload.secret_code) {
            payload.secret_code = lastSignupPayload.secret_code;
        }
        if (lastSignupPayload && lastSignupPayload.company_id) {
            payload.company_id = lastSignupPayload.company_id;
        }
        if (lastSignupPayload && lastSignupPayload.email) {
            payload.email = lastSignupPayload.email;
        }
        if (lastSignupPayload && lastSignupPayload.note) {
            payload.note = lastSignupPayload.note;
        }
        return payload;
    }

    function statusClass(kind) {
        if (kind === 'success') {
            return 'acpec-status acpec-status-success';
        }
        if (kind === 'error') {
            return 'acpec-status acpec-status-error';
        }
        if (kind === 'pending') {
            return 'acpec-status acpec-status-pending';
        }
        return 'acpec-status acpec-status-neutral';
    }

    function setResult(label, text, kind) {
        resultStatus.className = statusClass(kind);
        resultStatus.textContent = label;
        resultBox.value = text || '';
    }

    function buildOptions() {
        selector.innerHTML = '';
        apiCatalog.forEach(function (item, index) {
            const option = document.createElement('option');
            option.value = String(index);
            option.textContent = '[' + item.group + '] ' + item.label;
            selector.appendChild(option);
        });
    }

    function applySample() {
        const idx = parseInt(selector.value || '0', 10);
        const item = apiCatalog[idx];
        if (!item) {
            return;
        }
        methodInput.value = 'POST (JSON-RPC)';
        endpointInput.value = item.route || '/';
        payloadInput.value = JSON.stringify(applyOtpContext(item, deepClone(item.payload || {})), null, 2);
        apiNote.textContent = item.note || '';
    }

    async function sendRequest() {
        const endpoint = endpointInput.value || '/';
        let userPayload = {};

        try {
            userPayload = payloadInput.value ? JSON.parse(payloadInput.value) : {};
        } catch (error) {
            setResult('JSON invalide', 'Erreur de parsing : ' + error.toString(), 'error');
            return;
        }

        const jsonRpcPayload = {
            jsonrpc: '2.0',
            method: 'call',
            params: userPayload,
            id: Date.now()
        };

        accessToken = accessTokenBox.value || accessToken;
        refreshToken = refreshTokenBox.value || refreshToken;

        const headers = {
            'Content-Type': 'application/json'
        };
        if (accessToken) {
            headers.Authorization = 'Bearer ' + accessToken;
        }
        if (refreshToken) {
            headers['X-ACPEC-Refresh-Token'] = refreshToken;
        }

        const options = {
            method: 'POST',
            credentials: 'same-origin',
            headers: headers,
            body: JSON.stringify(jsonRpcPayload)
        };

        setResult('En cours', 'Appel JSON-RPC POST vers ' + endpoint + ' ...', 'pending');

        try {
            const response = await fetch(endpoint, options);
            const result = await response.json();
            captureTokens(result);
            captureOtpContext(result, userPayload, endpoint);
            const formatted = JSON.stringify(result, null, 2);

            if (!response.ok) {
                setResult('HTTP ' + response.status, formatted, 'error');
            } else if (result.error) {
                setResult('SERVER ERROR', formatted, 'error');
            } else if (result.result && result.result.ok === false) {
                setResult('API ERROR', formatted, 'error');
            } else {
                setResult('200 OK', formatted, 'success');
            }
        } catch (error) {
            setResult('Erreur réseau ou format', error.toString(), 'error');
        }
    }

    buildOptions();
    applySample();

    selector.addEventListener('change', applySample);
    resetButton.addEventListener('click', applySample);
    clearButton.addEventListener('click', function () {
        setResult('Aucun appel', '', 'neutral');
    });
    clearTokensButton.addEventListener('click', function () {
        clearTokens();
        setResult('Tokens vidés', '', 'neutral');
    });
    syncTokenBoxes();
    sendButton.addEventListener('click', sendRequest);
})();
